let count = kcontext.getVariable("retryCount");
kcontext.setVariable("retryCount", count + 1);

console.log("[BPM][RETRY] process=pru-api-error-handler | piid=" + kcontext.getProcessInstance().getId() + " | node=IncrementRetry | caseId=" + kcontext.getVariable("caseId") + " | attempt=" + (count + 1) + " | maxRetries=" + kcontext.getVariable("maxRetryCount") + " | failedEndpoint=" + kcontext.getVariable("failedEndpoint"));

// 1. Initialize Base URL
let url = ((env && env["INTEGRATION_LAYER_URL"]) || "");
if (url == null || url.isEmpty()) { url = ((env && env["INTEGRATION_LAYER_URL"]) || ""); }
if (url == null || url.isEmpty()) {
    try {
        url = kcontext.getKieRuntime().getEnvironment().get("INTEGRATION_LAYER_URL");
    } catch (e) {
        console.log("[BPM][EXIT][ERROR] process=pru-api-error-handler | piid=" + kcontext.getProcessInstance().getId() + " | node=ParseContext | caseId=" + kcontext.getVariable("caseId") + " | error=" + e.getMessage());
    }
}
if (url == null || url.isEmpty()) { url = "http://localhost:3000"; }
kcontext.setVariable("baseUrl", url);

console.log("[BPM][BOOTSTRAP] process=pru-api-error-handler | piid=" + kcontext.getProcessInstance().getId() + " | caseId=" + kcontext.getVariable("caseId") + " | baseUrl=" + url);

// 2. Initialize default retry states if empty
if (kcontext.getVariable("retryCount") == null) { kcontext.setVariable("retryCount", 0); }
if (kcontext.getVariable("maxRetryCount") == null) { kcontext.setVariable("maxRetryCount", 3); }

// 3. Unpack the JSON context sent from the main process
let ctx = kcontext.getVariable("failedContext");

console.log("[BPM][ENTRY] process=pru-api-error-handler | piid=" + kcontext.getProcessInstance().getId() + " | node=ParseContext | caseId=" + kcontext.getVariable("caseId") + " | failedContext=" + (ctx != null ? ctx.substring(0, Math.min(ctx.length, 200)) : "null"));
if (ctx != null && !ctx.isEmpty()) {
    try {
        let node = new com.fasterxml.jackson.databind.ObjectMapper().readTree(ctx);
        let endpoint = node.get("url").asText();
        if (!endpoint.startsWith("http")) {
            endpoint = url + endpoint;
        }
        kcontext.setVariable("failedEndpoint", endpoint);
        kcontext.setVariable("failedPayload", node.get("payload").toString());

        let method = "POST";
        if (node.has("method")) {
            method = node.get("method").asText();
        }
        kcontext.setVariable("failedMethod", method);

        let headers = "";
        if (node.has("headers")) {
            headers = node.get("headers").asText();
        }
        kcontext.setVariable("failedHeaders", headers);

        console.log("[BPM][EXIT][OK] process=pru-api-error-handler | piid=" + kcontext.getProcessInstance().getId() + " | node=ParseContext | caseId=" + kcontext.getVariable("caseId") + " | failedEndpoint=" + endpoint + " | failedMethod=" + method + " | failedHeaders=" + headers);
    } catch (e) {
        console.log("[BPM][EXIT][ERROR] process=pru-api-error-handler | piid=" + kcontext.getProcessInstance().getId() + " | node=ParseContext | caseId=" + kcontext.getVariable("caseId") + " | error=" + e.getMessage());
    }
}
// Default method if not unpacked
if (kcontext.getVariable("failedMethod") == null) { kcontext.setVariable("failedMethod", "POST"); }
if (kcontext.getVariable("failedHeaders") == null) { kcontext.setVariable("failedHeaders", ""); }

let signalData = kcontext.getVariable("certGenSignalResponse");
console.log("[BPM][EXIT] process=certificate_document_generation | piid=" + kcontext.getProcessInstance().getId() + " | node=Wait-Certificate-Generation-Signal | caseId=" + kcontext.getVariable("caseId") + " | signalData=" + signalData);
// Poller-driven signal (apl-policy-ms CertificateGeneration's runBatchSweep) replaces the old
// timer-poll loop entirely - it raises CERTIFICATE_DOCUMENT_GENERATION_SIGNAL exactly once,
// carrying {success, lineageId}, once every certificate sharing a lineage_id has resolved (or one
// of them timed out). There's no more in-flight "Pending" state to loop on here - the signal only
// ever fires Completed or Failed, never partway through.
let success = false;
if (signalData != null) {
    let successVal = signalData.get("success");
    success = Boolean.TRUE.equals(successVal) || "true".equals(String(successVal));
}
kcontext.setVariable("generationStatus", success ? "Completed" : "Failed");
kcontext.setVariable("certificateResults", signalData != null ? signalData.toString() : null);

console.log("[BPM][ENTRY] process=certificate_document_generation | piid=" + kcontext.getProcessInstance().getId() + " | node=Build-Certificate-Create-Payload | caseId=" + kcontext.getVariable("caseId") + " | journeyType=" + kcontext.getVariable("journeyType"));
// CertificateGeneration/apis.ts checkRequestBody requires party_id + type; party_agreement_ids
// (plural, array) is genuinely looped per-agreement by createCertificatesLoop, not just accepted
// for shape compatibility - this subprocess's own party_agreement_ids carries the real scope
// straight through, so a resend/regenerate call covering several agreements generates all of
// them in one call, the same as the real endpoint supports.
// change_reason is optional (createCertificatesLoop's own logic decides INITIAL_ISSUE/REPRINT/
// default_change_reason when omitted) - only required at all for journeys whose policy_document_type
// rows are marked change_reason_required (currently just CORRECTION), and even then only on a reissue.
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.putPOJO("party_id", kcontext.getVariable("party_id"));
let createPartyAgreementIdsNode ;
try {
    createPartyAgreementIdsNode = new com.fasterxml.jackson.databind.ObjectMapper().readTree(kcontext.getVariable("party_agreement_ids"));
} catch (e) {
    createPartyAgreementIdsNode = new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode();
}
json.set("party_agreement_ids", createPartyAgreementIdsNode);
json.putPOJO("type", kcontext.getVariable("journeyType"));
let changeReasonVal = kcontext.getVariable("changeReason");
if (changeReasonVal != null && !String(changeReasonVal).isEmpty()) {
    json.putPOJO("change_reason", changeReasonVal);
}
// This subprocess now waits on CERTIFICATE_DOCUMENT_GENERATION_SIGNAL instead of polling (see
// Wait-Certificate-Generation-Signal) - cid/piid/signal_name are required on every call so
// apl-policy-ms's CertificateGeneration/flows.ts poller can raise that signal back once every
// certificate under this request's lineage_id resolves. signal_name must be this exact literal;
// it's the one name this subprocess's own catch event is wired to (jBPM signal names are resolved
// statically at design time - a caller-supplied name can't change what this catch event listens for).
// piid must be THIS subprocess instance's own id, not a caller-supplied value - a callActivity's
// parent can't know its child's instance id before the child actually starts, so no caller could
// ever have populated this correctly. cid falls back to caseId when the caller has no distinct
// case-level id of its own (e.g. certificate-resend.bpmn only ever supplies caseId, never cid) -
// matching error-retry/register's identical cid-is-soft/piid-is-authoritative contract in apl-policy-ms.
let cidVal = kcontext.getVariable("cid");
json.putPOJO("cid", cidVal != null ? cidVal : kcontext.getVariable("caseId"));
json.putPOJO("piid", kcontext.getProcessInstance().getId());
json.put("signal_name", "CERTIFICATE_DOCUMENT_GENERATION_SIGNAL");
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("certificateCreateUrl"));
kcontext.setVariable("ContentData", json.toString());
kcontext.setVariable("ContentType", "application/json");
kcontext.setVariable("ResultClass", "");
kcontext.setVariable("ConnectTimeout", "180000");
kcontext.setVariable("ReadTimeout", "180000");
kcontext.setVariable("HandleResponseErrors", "true");
kcontext.setVariable("Headers", "{\"Content-Type\":\"application/json\"}");

let resp = kcontext.getVariable("Result");
console.log("[BPM][EXIT] process=certificate_document_generation | piid=" + kcontext.getProcessInstance().getId() + " | node=Request-Certificate-Document | caseId=" + kcontext.getVariable("caseId") + " | responseLen=" + (resp != null ? String(resp.length) : "null"));
// /policy/certificate/create returns a JSON ARRAY (one entry per document type) on success, or a
// plain {"error": "..."} object on a request-level failure (missing fields, agreement not found) -
// see CertificateGeneration/apis.ts checkRequestBody / resolveAgreementForCreate. An object-level
// error means there's nothing to poll for - fail fast instead of waiting a full minute to find out.
let createFailed = false;
if (resp == null || resp.isEmpty()) {
    createFailed = true;
} else {
    try {
        let root = new com.fasterxml.jackson.databind.ObjectMapper().readTree(resp);
        if (!root.isArray() && root.has("error")) {
            createFailed = true;
            console.log("[BPM][WARN] certificate create request-level error: " + root.get("error").asText());
        }
    } catch (e) {
        createFailed = true;
        console.log("[BPM][WARN] Could not parse certificate create response: " + e.getMessage());
    }
}
kcontext.setVariable("createFailed", createFailed);

console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | node=Build-Communication-Context | caseId=" + kcontext.getVariable("caseId"));
// commPurposeId is a declared process property, so a caller creating this case/process
// instance can supply its own value; MANUAL_RESEND below is only the fallback when none is
// given. MANUAL_RESEND is already seeded in communication_event_config (Category B,
// communication_event_config_seed_data.md) and flagged there as having "no sendCommunication
// call site designed yet" - this process is that call site. It covers both paths this process
// has (NO_CHANGE and a completed regeneration): "resolved dynamically, not a fixed role set" -
// primary recipient is whichever party (insured/group/broker) actually requested the resend,
// not a hardcoded role. partyAgreementIds/changeReason/generationRequired ride inside
// commEntityContext (not separate subprocess properties) so send_communication_with_retry.bpmn's
// own ioSpecification never needed touching - it already passes this whole object through.
// party_agreement_ids is a JSON-array-as-string process variable (same convention as
// policy_management_process.bpmn's own party_agreement_ids) - parsed here into a real array so
// CertificateSendEmail/apis.ts (which genuinely loops every id given, not just the first) gets
// the whole scope in one send-communication call, matching what /policy/certificate/create and
// /policy/certificates/status already do for the same field.
let entityContext = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
entityContext.putPOJO("partyId", kcontext.getVariable("party_id"));
entityContext.putPOJO("groupId", kcontext.getVariable("group_id"));
entityContext.putPOJO("brokerId", kcontext.getVariable("broker_id"));
let partyAgreementIdsNode ;
try {
    partyAgreementIdsNode = new com.fasterxml.jackson.databind.ObjectMapper().readTree(kcontext.getVariable("party_agreement_ids"));
} catch (e) {
    partyAgreementIdsNode = new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode();
}
entityContext.set("partyAgreementIds", partyAgreementIdsNode);
entityContext.putPOJO("changeReason", kcontext.getVariable("changeReason"));
entityContext.putPOJO("generationRequired", !"NO_CHANGE".equals(kcontext.getVariable("reasonMode")));
let certificateIdsNode ;
try {
    certificateIdsNode = new com.fasterxml.jackson.databind.ObjectMapper().readTree(kcontext.getVariable("certificateIds"));
} catch (e) {
    certificateIdsNode = new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode();
}
entityContext.set("certificateIds", certificateIdsNode);
kcontext.setVariable("commEntityContext", entityContext);
if (kcontext.getVariable("commPurposeId") == null || String(kcontext.getVariable("commPurposeId")).isEmpty()) {
    kcontext.setVariable("commPurposeId", "MANUAL_RESEND");
}

nodes.onEntry:
console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | node=Open-Timeline | caseId=" + kcontext.getVariable("caseId"));
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.put("partyId", kcontext.getVariable("party_id") + "");
json.putNull("policyId");
json.put("transactionType", "CERTIFICATE_RESEND");
json.put("requestedBy", "SYSTEM");
json.put("sourceChannel", "BPM");
