console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | node=Close-Timeline-COMPLETED | caseId=" + kcontext.getVariable("caseId"));
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
