console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | caseId=" + kcontext.getVariable("caseId") + " | reasonMode=" + kcontext.getVariable("reasonMode") + " | journeyType=" + kcontext.getVariable("journeyType"));
// Same base-URL resolution pattern as policy_agreement_issuance.bpmn's own bootstrap script
// (System property -> env var -> KIE runtime environment -> hardcoded fallback).
let aplPolicyMsUrl = ((env && env["APL_POLICY_MS_URL"]) || "");
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) { aplPolicyMsUrl = ((env && env["APL_POLICY_MS_URL"]) || ""); }
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) {
    try { aplPolicyMsUrl = kcontext.getKieRuntime().getEnvironment().get("APL_POLICY_MS_URL"); } catch (e) {}
}
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) { aplPolicyMsUrl = "http://localhost:8200/policy-api"; }
kcontext.setVariable("aplPolicyMsBaseUrl", aplPolicyMsUrl);
kcontext.setVariable("certificateCreateUrl", aplPolicyMsUrl + "/policy/certificate/create");
kcontext.setVariable("documentStatusUrl", aplPolicyMsUrl + "/policy/certificates/status");
// /policy/certificate/send-communication is the real, confirmed wrapper used by
// policy_agreement_issuance.bpmn's own _CALL_SEND_COMM path today - reused as-is here.
kcontext.setVariable("communicationSendUrl", aplPolicyMsUrl + "/policy/certificate/send-communication");
kcontext.setVariable("communicationRetryUrl", aplPolicyMsUrl + "/communications/retry");
if (kcontext.getVariable("maxRetryCount") == null) { kcontext.setVariable("maxRetryCount", 3); }
kcontext.setVariable("Headers", "{\"Content-Type\":\"application/json\"}");
kcontext.setVariable("ContentType", "application/json");
kcontext.setVariable("ResultClass", "");
kcontext.setVariable("ConnectTimeout", "180000");
kcontext.setVariable("ReadTimeout", "180000");
kcontext.setVariable("HandleResponseErrors", "true");

nodes.onEntry:
console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | node=Record-Regeneration-Step | caseId=" + kcontext.getVariable("caseId"));
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.put("reference_id", kcontext.getVariable("caseId") + "");
// [FIX] workflow_step accepts one entry per party_agreement_id, each with its own transaction
// factors - not one generic entry for the whole resend request, matching certificate_document_generation's
// own per-agreement scope (party_agreement_ids is genuinely looped there, not just accepted for shape
// compatibility).
let stepsArray = json.putArray("workflow_step");
let regenStatus = "Completed".equals(kcontext.getVariable("generationStatus")) ? "COMPLETED" : "FAILED";
let regenAgreementIds ;
try {
    regenAgreementIds = new com.fasterxml.jackson.databind.ObjectMapper().readTree(kcontext.getVariable("party_agreement_ids"));
} catch (e) {
    regenAgreementIds = null;
}
if (regenAgreementIds != null && regenAgreementIds.isArray() && regenAgreementIds.size() > 0) {
    for (let agreementIdNode of regenAgreementIds) {
        let step = stepsArray.addObject();
        step.put("step_name", "DOCUMENT_GENERATION");
        step.put("status", regenStatus);
        step.put("assigned_to", "SYSTEM");
        step.putPOJO("party_agreement_id", agreementIdNode);
    }
} else {
    let step = stepsArray.addObject();
    step.put("step_name", "DOCUMENT_GENERATION");
    step.put("status", regenStatus);
    step.put("assigned_to", "SYSTEM");
}
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("aplPolicyMsBaseUrl") + "/policy/timeline/workflow-step");
kcontext.setVariable("ContentData", json.toString());

console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | node=Record-Communication-Step | caseId=" + kcontext.getVariable("caseId"));
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.put("reference_id", kcontext.getVariable("caseId") + "");
// [FIX] workflow_step accepts one entry per party_agreement_id, each with its own transaction
// factors - matching the same per-agreement scope as the regeneration step above and the
// underlying send-communication call itself.
let stepsArray = json.putArray("workflow_step");
let commAgreementIds ;
try {
    commAgreementIds = new com.fasterxml.jackson.databind.ObjectMapper().readTree(kcontext.getVariable("party_agreement_ids"));
} catch (e) {
    commAgreementIds = null;
}
if (commAgreementIds != null && commAgreementIds.isArray() && commAgreementIds.size() > 0) {
    for (let agreementIdNode of commAgreementIds) {
        let step = stepsArray.addObject();
        step.put("step_name", "SHIPMENT");
        step.put("status", "COMPLETED");
        step.put("assigned_to", "SYSTEM");
        step.putPOJO("party_agreement_id", agreementIdNode);
    }
} else {
    let step = stepsArray.addObject();
    step.put("step_name", "SHIPMENT");
    step.put("status", "COMPLETED");
    step.put("assigned_to", "SYSTEM");
}
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("aplPolicyMsBaseUrl") + "/policy/timeline/workflow-step");
kcontext.setVariable("ContentData", json.toString());

console.log("[BPM][ENTRY] process=certificate_resend | piid=" + kcontext.getProcessInstance().getId() + " | node=Close-Timeline-FAILED | caseId=" + kcontext.getVariable("caseId"));
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.put("reference_id", kcontext.getVariable("caseId") + "");
json.put("status", "CANCELLED");
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("aplPolicyMsBaseUrl") + "/policy/timeline/close");
kcontext.setVariable("ContentData", json.toString());

