let urlVal = kcontext.getVariable("Url");
let methodVal = kcontext.getVariable("Method");
let errorMsg = kcontext.getVariable("ErrorMessage");

if (kcontext.getVariable("caseId") == null) { kcontext.setVariable("caseId", ""); }
if (kcontext.getVariable("maxRetryCount") == null) { kcontext.setVariable("maxRetryCount", 3); }
if (kcontext.getVariable("count") == null) { kcontext.setVariable("count", 1); }
if (kcontext.getVariable("Method") == null) { kcontext.setVariable("Method", "POST"); }

console.log("[BPM][ENTRY] process=policy_system.error_flow | piid=" + kcontext.getProcessInstance().getId() + " | node=Init | caseId=" + kcontext.getVariable("caseId") + " | url=" + urlVal + " | method=" + methodVal + " | maxRetryCount=" + kcontext.getVariable("maxRetryCount") + " | count=" + kcontext.getVariable("count") + " | errorMessage=" + errorMsg);

// Builds the request for /error-retry/register - this hands the actual wait
// off to an external tracker (error_retry_tracker) + poller instead of a
// BPMN timerEventDefinition, because this KIE Server build's EJB Timer
// Service crashes the marshaller on every commit that
// resumes an active gateway from a background thread. The poller instead
// nudges this instance forward with a plain signal, delivered via an
// ordinary synchronous REST call - the same code path that has run every
// gateway evaluation cleanly all along.
let aplPolicyMsUrl = ((env && env["APL_POLICY_MS_URL"]) || "");
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) { aplPolicyMsUrl = ((env && env["APL_POLICY_MS_URL"]) || ""); }
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) {
    try { aplPolicyMsUrl = kcontext.getKieRuntime().getEnvironment().get("APL_POLICY_MS_URL"); } catch (e) {}
}
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) { aplPolicyMsUrl = "http://localhost:3002"; }

// signal_name here is stored for the case-service's own cid/piid-scoped
// correlation (sendCaseSignal), not for jBPM's own catch event - jBPM's
// signalRef is a fixed literal ("ErrorRetrySignal") for every instance, and
// per-instance targeting instead comes from the poller always delivering it
// through the instance-scoped REST endpoint (.../instances/{piid}/signal/...),
// confirmed live: a signal fired through that endpoint only ever resumes the
// one matching instance, never a different one also waiting on the same name.
let piid = kcontext.getProcessInstance().getId();
let sigName = "ErrorRetry_" + piid;
kcontext.setVariable("signalName", sigName);
kcontext.setVariable("RegisterUrl", aplPolicyMsUrl + "/error-retry/register");

// RegisterContentData is an Object variable (not String) so RESTWorkItemHandler's own
// transformRequest(content, "application/json") - already the fixed ContentType on
// Register Retry - does the one real Jackson serialization itself. Building this as a
// pre-stringified String and letting DataFabric's context column be a bare varchar(255)
// is what originally caused every non-trivial retry context (anything beyond a tiny
// payload like {case_id, case_status}) to be silently rejected by Postgres
// ("value too long for type character varying(255)") - confirmed live. context.context
// is now itself a real nested Map rather than a second layer of stringified JSON, matching
// error_retry_tracker.context's own type now being json/jsonb, not varchar.
let rawContentData = kcontext.getVariable("ContentData");
let parsedContentData = rawContentData;
try {
    parsedContentData = new com.fasterxml.jackson.databind.ObjectMapper().readValue(rawContentData, java.util.Map);
} catch (e) {
    console.log("[BPM][WARN] process=policy_system.error_flow | piid=" + piid + " | node=Build-Register-Request | ContentData was not valid JSON, storing as a raw string - " + e.getMessage());
}

let retryContext = new java.util.LinkedHashMap();
retryContext.put("url", kcontext.getVariable("Url"));
retryContext.put("method", kcontext.getVariable("Method"));
retryContext.put("contentData", parsedContentData);

let body = new java.util.LinkedHashMap();
body.put("type", "API_RETRY");
body.put("cid", kcontext.getVariable("caseId"));
body.put("piid", String(piid));
body.put("signal_name", sigName);
body.put("context", retryContext);

kcontext.setVariable("RegisterContentData", body);

console.log("[BPM][ENTRY] process=policy_system.error_flow | piid=" + piid + " | node=Build-Register-Request | caseId=" + kcontext.getVariable("caseId") + " | signalName=" + sigName);

let raw = kcontext.getVariable("signalData");
let success = false;
let exceeded = false;
let responsePayload = null;
try {
  let rawMap = null;
  if (raw instanceof java.util.Map) {
    rawMap = raw;
  } else if (raw instanceof com.fasterxml.jackson.databind.JsonNode) {
    rawMap = new com.fasterxml.jackson.databind.ObjectMapper().convertValue(raw, java.util.Map);
  } else if (raw != null) {
    rawMap = new com.fasterxml.jackson.databind.ObjectMapper().readValue(String(raw), java.util.Map);
  }
  if (rawMap != null) {
    let s = rawMap.get("success");
    success = Boolean.TRUE.equals(s) || "true".equals(String(s));
    let ex = rawMap.get("exceeded");
    exceeded = Boolean.TRUE.equals(ex) || "true".equals(String(ex));
    responsePayload = rawMap.get("response");
  }
} catch (e) {
  console.log("[BPM][WARN] Could not parse signalData: " + e.getMessage());
}
kcontext.setVariable("Status", success ? "200" : "FAILED");

// [FIX] This process's own "Result" is what the global RESTWorkItemHandler-decorator mapping
// copies onto the ORIGINAL failing process's own "Result" variable once this error_flow
// instance completes (confirmed live: left unset, the original process's Result ended up
// holding THIS process's earlier Register-Retry call's own response instead of the real
// retried business response - that leftover value has no "error" key, so the original
// process's own Result-parsing logic silently misread it as success and hung forever at its
// next wait state). Writing the real retried response (or a proper error-shaped object on
// failure/exceeded) here means the original process gets back exactly what a direct
// successful/failed REST call would have produced.
let resultMapper = new com.fasterxml.jackson.databind.ObjectMapper();
if (success) {
    kcontext.setVariable("Result", responsePayload != null ? resultMapper.writeValueAsString(responsePayload) : "{}");
} else {
    let errNode = resultMapper.createObjectNode();
    errNode.put("error", exceeded ? "Retry exceeded maximum wait time" : "Retry failed");
    kcontext.setVariable("Result", errNode.toString());
}

console.log("[BPM][EXIT] process=policy_system.error_flow | piid=" + kcontext.getProcessInstance().getId() + " | node=Parse-Signal-Result | success=" + success + " | exceeded=" + exceeded);

