let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.put("reference_id", kcontext.getVariable("cid") + "");
// [FIX] workflow_step accepts one entry per party_agreement_id, each carrying its own
// transaction factors - not a single generic entry for the whole case. Every agreement in
// this request's party_agreement_ids gets its own recorded step, matching how
// /policy/certificate/create and the _CALL_ISSUE_CHILD multi-instance fan-out already scope
// everything else in this process per-agreement rather than per-case.
let stepsArray = json.putArray("workflow_step");
let siuFlaggedNow = Boolean.TRUE.equals(kcontext.getVariable("siu_flagged"));
let agreementIdsForStep = kcontext.getVariable("party_agreement_ids");
if (agreementIdsForStep == null || agreementIdsForStep.isEmpty()) {
    let step = stepsArray.addObject();
    step.put("step_name", "SIU_HOLD_CHECK");
    step.put("status", siuFlaggedNow ? "HELD" : "COMPLETED");
    step.put("assigned_to", "SYSTEM");
} else {
    for (let agreementId of agreementIdsForStep) {
        let step = stepsArray.addObject();
        step.put("step_name", "SIU_HOLD_CHECK");
        step.put("status", siuFlaggedNow ? "HELD" : "COMPLETED");
        step.put("assigned_to", "SYSTEM");
        step.putPOJO("party_agreement_id", agreementId);
    }
}
// transaction_factor has no party_agreement_id field of its own (confirmed against apl-policy-ms's
// own validation - only {factor, approved} per entry) - SIU is a party-level check anyway (one
// person, not per-agreement), so one factor entry per transaction is the schema-correct scope here,
// distinct from workflow_step's own per-agreement fan-out above.
let factorsArray = json.putArray("transaction_factor");
let siuFactor = factorsArray.addObject();
siuFactor.put("factor", "SIU_FLAGGED");
siuFactor.put("approved", !siuFlaggedNow);
kcontext.setVariable("Url", kcontext.getVariable("timelineStepUrl"));
