let signalData = kcontext.getVariable("certBatchSignalResponse");
console.log("[BPM][EXIT] process=policy_issue | piid=" + kcontext.getProcessInstance().getId() + " | node=Wait-Certificate-Batch-Generation-Signal | caseId=" + kcontext.getVariable("caseId") + " | signalData=" + signalData);
// Poller-driven signal (apl-policy-ms CertificateGeneration's runBatchSweep) - fires exactly
// once, carrying {success, lineageId}, once every certificate sharing this batch's lineage_id
// has resolved (or one of them timed out). Same mechanism certificate-document-generation.bpmn's
// own _PARSE_SIGNAL_RESULT already relies on.
let success = false;
if (signalData != null) {
    let successVal = signalData.get("success");
    success = Boolean.TRUE.equals(successVal) || "true".equals(String(successVal));
}
kcontext.setVariable("cert_batch_status", success ? "Completed" : "Failed");

console.log("[BPM][ENTRY] process=policy_issue | piid=" + kcontext.getProcessInstance().getId() + " | node=Build-OFAC-Decision-Payload | caseId=" + kcontext.getVariable("caseId"));
// Persists the reviewer's OFAC decision back to apl-policy-ms
// (POST /ofac/case/decision) once _HOLD_OFAC completes, before
// _GATE_OFAC_DECISION branches. Maps this process's 3-way reviewer_decision
// (plus the "no approval document" override _GATE_OFAC_DECISION's own
// _F_GATE_OFAC_DECISION_ESCALATE condition already enforces) onto the API's
// own decision enum (APPROVE/DECLINE/ESCALATE_LEGAL -
// OFAC_check/flows.ts sd_L34UTvXMwXFvhBpA) - mirrors that same condition
// exactly, so the persisted decision always matches the branch actually taken.
let rd = kcontext.getVariable("reviewer_decision");
let docId = kcontext.getVariable("ofac_approval_document_id");
let apiDecision ;
if ("DECLINE".equals(rd)) {
    apiDecision = "DECLINE";
} else if ("ESCALATE".equals(rd)) {
    apiDecision = "ESCALATE_LEGAL";
} else {
    apiDecision = "APPROVE";
}
// [KNOWN GAP] escalation_subject is required by the API for ESCALATE_LEGAL but
// no real Case Manager screen field for it is confirmed yet (docs/design.md
// section 8) - _HOLD_OFAC can supply one if/when that field exists; until
// then this synthesizes a safe non-empty default so the call never 400s.
let escSubject = kcontext.getVariable("escalation_subject");
if (escSubject == null || escSubject.trim().isEmpty()) {
    escSubject = "OFAC Compliance Review - Legal Escalation - Case " + kcontext.getVariable("cid");
}
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.putPOJO("cid", kcontext.getVariable("cid"));
json.putPOJO("piid", kcontext.getProcessInstance().getId());
json.putPOJO("party_id", kcontext.getVariable("party_id"));
json.put("decision", apiDecision);
json.putPOJO("document_id", docId);
// [KNOWN GAP] No real per-user identity is captured by this human task today
// (only the ProcessReviewer role) - reviewer is the role name as a placeholder
// until a real ActorId/ownership capture is wired into _HOLD_OFAC.
json.put("reviewer", "ProcessReviewer");
if ("ESCALATE_LEGAL".equals(apiDecision)) {
    json.put("escalation_subject", escSubject);
}
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("ofacCaseDecisionUrl"));
kcontext.setVariable("ContentData", json.toString());

