// [FIX] Bare assignment (caseId = ...) does not reliably persist a process variable write
// in this KIE deployment's Java-dialect scriptTask compiler, confirmed live: every bare-assigned
// variable below showed empty in a running instance's Process Variables view, while every
// kcontext.setVariable(...) call in this same script (the URL resolution further down) came
// through correctly. Every assignment in this script now uses the proven-working explicit form.
 kcontext.setVariable("piid", String(kcontext.getProcessInstance().getId()));
kcontext.setVariable("caseId", String(cid));
kcontext.setVariable("maxRetryCount", 3);
kcontext.setVariable("Method", "POST");
kcontext.setVariable("ContentType", "application/json");
// ResultClass intentionally empty - RESTWorkItemHandler only attempts JSON->Object transformation
// when ResultClass is set, and every downstream _PARSE_* script casts Result directly to String,
// expecting raw response text. Setting a class here (even "java.lang.String") makes Jackson try to
// deserialize the JSON body into that type, which fails for any object-shaped response body.
kcontext.setVariable("ResultClass", "");
kcontext.setVariable("ConnectTimeout", "180000");
kcontext.setVariable("ReadTimeout", "180000");
kcontext.setVariable("HandleResponseErrors", "true");
kcontext.setVariable("Headers", "{\"Content-Type\":\"application/json\"}");
// [FIX] Base URL resolution - matching the reference pru-nigo-followup.bpmn's real Script_Bootstrap pattern
// (System property -> env var -> KIE runtime environment -> hardcoded fallback). Every onEntry-script in
// this process previously built its Url from inert "${VAR}" placeholder text with NO real resolution
// mechanism anywhere in this kjar - confirmed by reading kie-deployment-descriptor.xml's own Rest work item
// handler (org.jbpm.process.workitem.rest.RESTWorkItemHandler, the real standard jBPM REST client, which
// performs no placeholder substitution of its own) and finding no custom WorkItemHandler or "${VAR}"
// substitution logic anywhere else in this kjar. Every onEntry-script now reads these resolved process
// variables via kcontext.getVariable(...) instead.
let aplQuotationMsUrl = ((env && env["APL_QUOTATION_MS_URL"]) || "");
if (aplQuotationMsUrl == null || aplQuotationMsUrl.isEmpty()) { aplQuotationMsUrl = ((env && env["APL_QUOTATION_MS_URL"]) || ""); } ;
if (aplQuotationMsUrl == null || aplQuotationMsUrl.isEmpty()) {
    try { aplQuotationMsUrl = kcontext.getKieRuntime().getEnvironment().get("APL_QUOTATION_MS_URL"); } catch (e) {}
};
if (aplQuotationMsUrl == null || aplQuotationMsUrl.isEmpty()) { aplQuotationMsUrl = "http://localhost:3001"; };
kcontext.setVariable("aplQuotationMsBaseUrl", aplQuotationMsUrl);

let aplPolicyMsUrl = ((env && env["APL_POLICY_MS_URL"]) || "");
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) { aplPolicyMsUrl = ((env && env["APL_POLICY_MS_URL"]) || ""); };
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) {
    try { aplPolicyMsUrl = kcontext.getKieRuntime().getEnvironment().get("APL_POLICY_MS_URL"); } catch (e) {}
};
if (aplPolicyMsUrl == null || aplPolicyMsUrl.isEmpty()) { aplPolicyMsUrl = "http://localhost:3002"; };
kcontext.setVariable("aplPolicyMsBaseUrl", aplPolicyMsUrl);

// [FIX] Every endpoint URL this process ever calls is assembled here, once, at process start - not
// piecemeal inside each stage's own onEntry-script. Every dynamic piece any of these URLs needs
// (party_id/group_id/policy_id/party_agreement_ids) is already available as a process-level property
// from the moment this process starts, so there is no stage for which the URL genuinely can't be known
// this early - only each stage's own JSON request body (which needs values resolved mid-flow, like
// certificate_id) still gets built inside that stage's own onEntry-script.
kcontext.setVariable("siuCheckUrl", aplPolicyMsUrl + "/policy/issuance/siu-check");
kcontext.setVariable("complexCoverageCheckUrl", aplPolicyMsUrl + "/policy/issuance/complex-coverage-check");
// [FIX] apl-quotation-ms's /v1/compliance/ofac/screen was an explicit [MOCK] placeholder pending real
// LexisNexis integration. apl-policy-ms now has a real, fully-built OFAC service (OFAC_check/apis.json)
// wired to LexisNexis and its own ofac_screening Data Fabric table - routed there instead, matching this
// process's own convention that every real call goes through apl-policy-ms.
kcontext.setVariable("ofacScreenUrl", aplPolicyMsUrl + "/ofac/screening/run");
// [NEW] Persist the reviewer's decision back to apl-policy-ms once _HOLD_CC/_HOLD_OFAC
// complete, so it's recorded against the real case/compliance record - not just used to
// branch this process locally. See _BUILD_CC_DECISION_PAYLOAD / _BUILD_OFAC_DECISION_PAYLOAD.
kcontext.setVariable("jetIssueDecisionUrl", aplPolicyMsUrl + "/jet-issue/decision");
kcontext.setVariable("ofacCaseDecisionUrl", aplPolicyMsUrl + "/ofac/case/decision");
kcontext.setVariable("premiumCheckUrl", aplPolicyMsUrl + "/policy/issuance/premium-check");
// Policy Record Creation (_CALL_REC in policy_agreement_issuance.bpmn) needs no URL here -
// party_agreement_id and every other agreement detail it needs is already known by the time
// that node runs, fanned out from party_agreement_ids below - it's a plain script, not a
// REST call.
// certificateCreateUrl/documentStatusUrl are both real apl-policy-ms endpoints (CertificateCreate/
// CertificateStatus sd-services), per "all policy-related APIs come from policy-ms only" - hardcoded stubs today
// pending the real implementation being built separately, but matching the exact request/response shape this
// process already sends/expects. documentStatusUrl carries no query string - Poll Document Status (in
// policy_agreement_issuance.bpmn) POSTs party_agreement_id/party_id/type in the request body instead, since
// the real endpoint is POST /policy/certificates/status, not a GET.
kcontext.setVariable("certificateCreateUrl", aplPolicyMsUrl + "/policy/certificate/create");
kcontext.setVariable("documentStatusUrl", aplPolicyMsUrl + "/policy/certificates/status");
// [CHANGED] certificateSendEmailUrl (apl-quotation-ms /policy/certificate/send-communication)
// replaced - communication now goes through the real apl-policy-ms Communication
// service, once for the whole process after every agreement is done, not per
// agreement (see _BUILD_COMM_PAYLOAD, between _CALL_ISSUE_CHILD and _END_ISSUED).
kcontext.setVariable("communicationSendUrl", aplPolicyMsUrl + "/policy/certificate/send-communication");
kcontext.setVariable("communicationRetryUrl", aplPolicyMsUrl + "/communications/retry");
kcontext.setVariable("shipmentsUrl", aplPolicyMsUrl + "/policy/shipments");
kcontext.setVariable("createPolicyUrl", aplPolicyMsUrl + "/policy/create-policy");

kcontext.setVariable("timelineOpenUrl", aplPolicyMsUrl + "/policy/timeline/open");
kcontext.setVariable("timelineStepUrl", aplPolicyMsUrl + "/policy/timeline/workflow-step");
kcontext.setVariable("timelineCloseUrl", aplPolicyMsUrl + "/policy/timeline/close");

