// POST /policy/issuance/complex-coverage-check - real apl-policy-ms endpoint (synchronous request/response;
// see APL Docs/apis/complex_coverage_check_apis.md). Replaces the old apl-quotation-ms /policy/issuance/check
// fire-and-forget call: that call never actually resolved this gate - it declared a "COMPLEX_COVERAGE_RESULT_SIGNAL"
// resume but no signal-catch event for it exists anywhere in this process, so audit_bypass was never set by
// anything and this gate always took the Bypass=No branch. [CHANGED] isRenewal used to be derived from a
// single party_agreement_id being already known; this gate now runs once per group, before the
// per-agreement fan-out below, so it re-derives the same signal from party_agreement_ids (the incoming
// array of existing agreement ids to issue - non-empty means at least one is already known). partyId is
// this specific insured (Group or Insured, per AMPL-122) - the check evaluates first-time-issuance
// against both the group's own state and this insured's own resolved state, and folds either being
// first-time into the single firstTimeIssuance flag read below, so no extra branching is needed here.
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.putPOJO("groupId", kcontext.getVariable("group_id"));
json.putPOJO("partyId", String(kcontext.getVariable("party_id")));
json.putPOJO("policyIssuedType", kcontext.getVariable("policy_issuance_type"));
json.put("isRenewal", false);
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("complexCoverageCheckUrl"));
kcontext.setVariable("ContentData", json.toString());

nodes.onExit:
let resp = kcontext.getVariable("Result");
console.log("[BPM][EXIT] process=policy_issue | piid=" + kcontext.getProcessInstance().getId() + " | node=Trigger-Complex-Coverage-Check | caseId=" + kcontext.getVariable("caseId") + " | responseLen=" + (resp != null ? String(resp.length) : "null"));
// response shape {data: {auditBypass: {passed, auditBypassValue, groupId}, productState: {firstTimeIssuance, resolvedState, products, productsFlaggedFirstTime}}}
// - see ComplexCoverageCheck/apis.ts finalResponseScript. audit_bypass=false alone doesn't hold every case -
// _GATE_CC_FIRST_TIME immediately after this stage only holds when this is also a first-time issuance in the
// state; a non-first-time case with audit_bypass=false continues instead, on the reading that the Complex
// Coverage concern (per AMPL-122) doesn't apply once a group is past its first issuance there. On a parse
// failure or empty response, first_time_issuance defaults to true (not false) so an unreadable result still
// routes to manual review rather than silently continuing with no human check at all.
if (resp != null && !resp.isEmpty()) {
    try {
        let root = new com.fasterxml.jackson.databind.ObjectMapper().readTree(resp);
        let data = root.path("data");
        kcontext.setVariable("audit_bypass", data.path("auditBypass").path("passed").asBoolean(false));
        kcontext.setVariable("first_time_issuance", data.path("productState").path("firstTimeIssuance").asBoolean(true));
    } catch (e) {
        console.log("[BPM][EXIT][ERROR] process=policy_issue | piid=" + kcontext.getProcessInstance().getId() + " | node=Trigger-Complex-Coverage-Check | error=" + e.getMessage());
        kcontext.setVariable("audit_bypass", false);
        kcontext.setVariable("first_time_issuance", true);
    }
} else {
    kcontext.setVariable("audit_bypass", false);
    kcontext.setVariable("first_time_issuance", true);
}

