console.log("[BPM][ENTRY] process=send_communication_with_retry | piid=" + kcontext.getProcessInstance().getId() + " | node=Parse-Send-Result | caseId=" + kcontext.getVariable("caseId"));
// POST /communications/send response: {results:[{partyId,role,channel,isCc,
// status,shipmentId}], sent}. The primary (non-CC) recipient gets one
// results[] entry per configured channel (EMAIL, PHYSICAL, or both), each
// with its own shipmentId. sent here means every one of the primary's
// channels came back SENT - failedChannels collects however many didn't
// (zero, one, or both), so the same retry path below handles any
// combination uniformly, no separate single/multiple-channel branching.
let sent = false;
let failedChannelsJson = "[]";
let resp = kcontext.getVariable("Result");
try {
  let root = new com.fasterxml.jackson.databind.ObjectMapper().readTree(resp);
  let failed = new com.fasterxml.jackson.databind.ObjectMapper().createArrayNode();
  let primaryCount = 0;
  for (let r of root.path("results")) {
    if (r.path("isCc").asBoolean(false)) {
      continue;
    }
    primaryCount++;
    if (!"SENT".equals(r.path("status").asText(""))) {
      let f = failed.addObject();
      f.put("shipmentId", r.hasNonNull("shipmentId") ? r.path("shipmentId").asText() : null);
      f.put("channel", r.hasNonNull("channel") ? r.path("channel").asText() : null);
    }
  }
  sent = primaryCount > 0 && failed.size() == 0;
  failedChannelsJson = failed.toString();
} catch (e) {
  console.log("[BPM][WARN] Could not parse communication response: " + e.getMessage());
}
kcontext.setVariable("commSent", sent);
kcontext.setVariable("failedChannels", failedChannelsJson);

console.log("[BPM][ENTRY] process=send_communication_with_retry | piid=" + kcontext.getProcessInstance().getId() + " | node=Build-Retry-Payload | caseId=" + kcontext.getVariable("caseId"));
// failedChannels always reflects the current outstanding failures (set by
// Parse-Send-Result the first time through, then re-set by Parse-Retry-Result
// on every loop back) - POST /communications/retry takes the whole list in
// one call and retries exactly those channels, whether that's one or both.
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
try {
  let failures = new com.fasterxml.jackson.databind.ObjectMapper().readTree(kcontext.getVariable("failedChannels"));
  json.putPOJO("failures", failures);
} catch (e) {
  json.putArray("failures");
}
json.put("commPurposeId", kcontext.getVariable("commPurposeId"));
json.putPOJO("entityContext", kcontext.getVariable("commEntityContext"));
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("communicationRetryUrl"));
kcontext.setVariable("ContentData", json.toString());

console.log("[BPM][EXIT] process=send_communication_with_retry | piid=" + kcontext.getProcessInstance().getId() + " | node=Set-Response | caseId=" + kcontext.getVariable("caseId") + " | commSent=" + kcontext.getVariable("commSent"));
// response is this reusable subprocess's own declared output (see the
// callActivity that invokes this process) - matches the same {response ->
// sub_process_status} convention already used for every other reusable
// subprocess call in this project (policy_management_process.bpmn).
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.put("sent", Boolean.TRUE.equals(kcontext.getVariable("commSent")));
kcontext.setVariable("response", json.toString());

console.log("[BPM][ENTRY] process=send_communication_with_retry | piid=" + kcontext.getProcessInstance().getId() + " | node=Build-Payload | caseId=" + kcontext.getVariable("caseId"));
// Reusable subprocess - commEntityContext/communicationSendUrl/communicationRetryUrl
// and the standard rest-executor plumbing (Headers, maxRetryCount, etc.) all arrive
// as inputs, already resolved once by whichever caller started this instance.
// [FIX] communicationSendUrl points at apl-policy-ms's own /policy/certificate/send-communication
// wrapper - that wrapper used to hardcode commPurposeId=CERTIFICATE_ISSUED and resolve its own
// mergeData/entityContext purely from party_id/group_id/broker_id, so forwarding only those three
// was consistent with what it could ever use. It's since been fixed to accept comm_purpose_id,
// party_agreement_ids, change_reason, generation_required, certificate_id - resolving real
// per-agreement certificate data and using the real purpose instead of a hardcoded one - so this
// node now forwards them too. commPurposeId is a separate top-level input this subprocess already
// receives (was never read here); the rest ride inside commEntityContext, forwarded when present
// via optional chaining that resolves to null (harmless) rather than throwing when a caller (e.g.
// policy_issue.bpmn's own _CALL_SEND_COMM) doesn't set them - existing callers see no behavior
// change. _BUILD_RETRY_PAYLOAD below is unchanged - retry still calls /communications/retry
// directly with the original nested {commPurposeId, entityContext} shape.
let entityContext = kcontext.getVariable("commEntityContext");
let json = new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode();
json.set("party_id", entityContext.path("partyId"));
json.set("group_id", entityContext.path("groupId"));
json.set("broker_id", entityContext.path("brokerId"));
let commPurposeIdVal = kcontext.getVariable("commPurposeId");
if (commPurposeIdVal != null) { json.put("comm_purpose_id", commPurposeIdVal.toString()); }
if (entityContext.has("certificateIds") && !entityContext.path("certificateIds").isNull()) {
    json.set("certificate_ids", entityContext.path("certificateIds"));
}
// CertificateSendEmail/apis.ts genuinely loops every id in party_agreement_ids, not just the
// first - commEntityContext carries the real array under partyAgreementIds (plural), forwarded
// as-is so a multi-agreement resend/regenerate sends one communication covering every agreement.
if (entityContext.has("partyAgreementIds") && !entityContext.path("partyAgreementIds").isNull()) {
    json.set("party_agreement_ids", entityContext.path("partyAgreementIds"));
}
if (entityContext.has("changeReason") && !entityContext.path("changeReason").isNull()) {
    json.set("change_reason", entityContext.path("changeReason"));
}
if (entityContext.has("generationRequired") && !entityContext.path("generationRequired").isNull()) {
    json.set("generation_required", entityContext.path("generationRequired"));
}
kcontext.setVariable("Method", "POST");
kcontext.setVariable("Url", kcontext.getVariable("communicationSendUrl"));
kcontext.setVariable("ContentData", json.toString());

console.log("[BPM][ENTRY] process=send_communication_with_retry | piid=" + kcontext.getProcessInstance().getId() + " | node=Parse-Retry-Result | caseId=" + kcontext.getVariable("caseId"));
// Same parsing as Parse-Send-Result, re-applied to the retry response -
// failedChannels is overwritten with whatever is still outstanding, so a
